  const draw=()=>{const r=speciate(sample,.01);root.querySelector('.micro-stage').innerHTML=ionsView(r.ions,{solid:sample==='solid',on,id:'story-ions',neutral:sample==='sugar'?'大量中性糖分子留在水中；微量 H⁺、OH⁻ 來自水':sample==='acetic'?'大部分醋酸分子仍未游離':''});root.querySelector('.ion-explanation').textContent={solid:'NaCl 晶格已有正負離子，但位置固定。',nacl:'NaCl 解離：Na⁺ + Cl⁻，正負電荷總量相等。',sugar:'糖保留中性分子，沒有像 NaCl 一樣解離；水仍有微量離子。',hcl:'HCl 分子在水中游離，主要形成 H⁺、Cl⁻，不是 Na⁺。',naoh:'NaOH 解離：Na⁺ + OH⁻，不是所有陰離子都叫 Cl⁻。',acetic:'CH₃COOH ⇌ H⁺ + CH₃COO⁻；仍有大量未游離分子。'}[sample];seen.add(samples.indexOf(sample));root.querySelectorAll('[data-sample]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.sample===sample));b.dataset.seen=String(seen.has(samples.indexOf(b.dataset.sample)));});state.explored[c.id]=[...seen];state.steps[c.id]=on?1:0;save();refresh();root.querySelector('[data-electric]').textContent=on?'關閉電場':'開啟電場';root.querySelector('.explore-status').textContent='已比較 '+seen.size+' / 6 種樣品'+(on?' · 電場已開啟':' · 開啟電場，觀察離子移動方向');root.querySelector('[data-electric]').setAttribute('aria-pressed',String(on));};
