 document.querySelector('#lesson').append(section);
 const activityLabel={story:'查採樣紀錄',ions:'追蹤離子',reactions:'比較反應',strength:'比較酸鹼',salts:'翻樣品卡',audit:'核對報告',final:'交出報告'}[c.type]||'動手實驗';
 section.querySelector('.card-header').dataset.station=String(c.id).padStart(2,'0');
 section.querySelector('.card-header').insertAdjacentHTML('afterend','<nav class="card-journey" aria-label="本卡學習路線" data-glossary-skip>'+['先猜一猜',activityLabel,'驗證想法'].map((t,i)=>'<button type="button" data-journey="'+i+'"><span>0'+(i+1)+'</span>'+t+'</button>').join('')+'</nav>');
 section.querySelector('.card-header').insertAdjacentHTML('beforeend','<div class="card-route" data-glossary-skip><div class="route-copy"><strong></strong><small></small></div><div class="card-progress"><span class="card-progress-label"></span><span class="card-progress-track"><i></i></span></div><button type="button" class="primary" data-continue></button></div>');
