 const activitySection=section.querySelector('.card-activity');activitySection.insertAdjacentHTML('afterend','<div class="activity-checkpoint" data-glossary-skip><div><small>接下來</small><strong></strong></div><button type="button" class="secondary" data-check-understanding>用一題驗證想法 →</button></div>');section.querySelector('[data-check-understanding]').onclick=()=>jumpTo(section.querySelector(state.observed.includes(c.id)?'.salt-quiz':'.task'));
  section.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>{activateStation(c.id);const target=section.querySelector(['.prediction','.task','.salt-quiz'][Number(b.dataset.journey)]);target.scrollIntoView({block:'start',behavior:'instant'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});
 if(c.id===12)section.querySelector('.card-body').insertAdjacentHTML('beforeend',"<section data-glossary-skip class=\"homecoming-ending\" id=\"homecoming\" aria-labelledby=\"homecoming-title\"><header><span class=\"eyebrow\">皇宮道別 · 開啟傳送門</span><h3 id=\"homecoming-title\">收好謝禮，我們回家吧！</h3><p>皇帝收下調查報告，將一只小木箱送給兩人作為謝禮。小葵抱好木箱，阿公啟動銀白色的時空裝置；金色傳送門在皇宮中緩緩展開。</p></header><figure><div class=\"homecoming-artwork\" role=\"img\" aria-label=\"小葵抱著皇帝贈送的小木箱，阿公在皇宮中啟動銀白色時空裝置，打開金色傳送門；門的另一側是擺著木質工作桌、黃銅儀器與綠色藤蔓的家中工坊，皇帝在後方揮手道別。\"></div><figcaption>小木箱是皇帝的謝禮；用證據解開謎題的經驗，是這趟旅程更珍貴的收穫。</figcaption></figure><div class=\"homecoming-dialogue\"><p><strong>小葵</strong>「謝謝陛下！阿公，我把小木箱抱好了，可以出發了！」</p><p><strong>阿公</strong>「走吧，把謝禮和好奇心一起帶回家。下次遇到問題，還是讓證據說話。」</p></div><p class=\"homecoming-finish\">兩人向皇帝揮手道別，帶著小木箱走向傳送門。</p></section>");
 const pred=state.predictions[c.id];if(pred!==undefined){section.querySelector('.prediction input[value="'+pred+'"]').checked=true;section.querySelector('.prediction-status').textContent='已記下預測。完成探索後，可回來修正想法。';}
 section.querySelectorAll('.prediction input').forEach(el=>el.onchange=()=>{state.predictions[c.id]=Number(el.value);section.querySelector('.prediction-status').textContent='已記下預測。完成探索後，可回來修正想法。';save();refresh();});
 const activity=section.querySelector('.card-activity');
 const ctrl=defaults[c.type]?mountLab(activity,c.type,{data:state.labs[c.type],completed:()=>state.observed.includes(c.id),save:v=>{state.labs[c.type]=v;save();refresh();},mark:()=>mark(c.id)}):mountStory(activity,c);controllers.set(c.id,ctrl);
 mountQuizzes(section);
 section.querySelector('.reset-card').onclick=()=>{controllers.get(c.id)?.destroy();delete state.predictions[c.id];delete state.notes[c.id];delete state.steps[c.id];delete state.explored[c.id];state.observed=state.observed.filter(id=>id!==c.id);for(const q of [c.quiz]){delete state.answers[q.id];delete state.attempts[q.id];}if(defaults[c.type])state.labs[c.type]=structuredClone(defaults[c.type]);save();const next=section.nextSibling;section.remove();renderCard(c);const replacement=document.querySelector('#salt-'+c.id);if(next)document.querySelector('#lesson').insertBefore(replacement,next);refresh();replacement.scrollIntoView({block:'start'});};
