function activateStation(id){document.querySelectorAll('[data-nav]').forEach(a=>{const active=Number(a.dataset.nav)===id;a.classList.toggle('active',active);if(active){a.setAttribute('aria-current','step');const nav=a.closest('nav'),top=a.getBoundingClientRect().top-nav.getBoundingClientRect().top+nav.scrollTop;if(top<nav.scrollTop||top+a.offsetHeight>nav.scrollTop+nav.clientHeight)nav.scrollTop=Math.max(0,top-nav.clientHeight/2+a.offsetHeight/2);}else a.removeAttribute('aria-current');});}
function init(){
 document.querySelector('#chapter-route').innerHTML=cards.map((c,i)=>(i===0||cards[i-1].act!==c.act?'<h3 class="nav-act">'+['','第一幕 · 辨認差異','第二幕 · 量測酸鹼','第三幕 · 控制反應','第四幕 · 製鹽挑戰'][c.act]+'</h3>':'')+'<a href="#salt-'+c.id+'" data-nav="'+c.id+'"><span>'+String(c.id).padStart(2,'0')+'</span><span>'+c.title+'</span><span class="nav-state">○</span></a>').join('');
 cards.forEach(renderCard);
 mountTerminology();
 document.querySelector('#clear-chapter-progress').onclick=()=>{for(const ctrl of controllers.values())ctrl.destroy();state=cleanState(null);save();document.querySelector('#lesson').innerHTML='';cards.forEach(renderCard);refresh();};
 document.querySelector('#export-progress').onclick=()=>{const payload={chapter:'皇帝最後的製鹽委託',exportedAt:new Date().toISOString(),mastered:cards.filter(mastered).map(c=>c.id),...state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='salt-adventure-learning-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 function route(){document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.hash===location.hash.replace(/^#activity-/,'#salt-');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});}
 addEventListener('hashchange',route);route();save();refresh();
 const tracker=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting)activateStation(Number(entry.target.closest('.salt-card').id.replace('salt-','')));},{rootMargin:'-5% 0px -65% 0px',threshold:0});document.querySelectorAll('.salt-card .card-header').forEach(h=>tracker.observe(h));
 if(/^#(?:salt|activity)-\d+$/.test(location.hash))requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView({block:'start'}));
 addEventListener('pagehide',()=>{for(const ctrl of controllers.values())ctrl.destroy();});
}
